'use strict';
// Original course writing, informed by the source books rather than PDF fragments.
window.CppCourseContent=(()=>{
 const pair=(vi,en)=>({vi,en});
 const example=(id,code,input,output)=>({id,code,input,output});
 const chapters=[
  ['start','Bắt đầu viết C++','Your first C++ programs'],['flow','Điều kiện và vòng lặp','Conditions and loops'],['functions','Hàm và kiểm thử','Functions and testing'],['data','Mảng, vector và chuỗi','Arrays, vectors and strings'],['memory','Con trỏ và bộ nhớ','Pointers and memory'],['objects','Cấu trúc và hướng đối tượng','Structures and objects'],['stl','STL và thuật toán','STL and algorithms'],['projects','Dự án tổng hợp','Practical projects']
 ].map(([id,vi,en])=>({id,title:pair(vi,en)}));
 const lessons=[
 {id:'program',title:pair('1. Chương trình đầu tiên','1. Your first program'),goal:pair('Hiểu chương trình bắt đầu ở đâu và in một dòng chữ.','Understand where execution begins and print one line.'),
 sections:[
  {title:pair('Từ mã nguồn đến kết quả','From source to output'),body:pair('Bạn viết mã C++ trong tệp .cpp. Trình biên dịch kiểm tra cú pháp và tạo chương trình thực thi. Khi bấm Chạy, chương trình bắt đầu tại hàm main. Lỗi biên dịch xảy ra trước khi chương trình chạy; kết quả sai là một vấn đề khác.','You write C++ in a .cpp file. The compiler checks its syntax and creates an executable. Running it starts execution in main. A compilation error happens before execution; a wrong result is a different problem.')},
  {title:pair('Đọc từng thành phần','Read the building blocks'),body:pair('#include <iostream> cung cấp công cụ nhập/xuất. int main() là điểm bắt đầu. Cặp { } bao quanh thân hàm. std::cout gửi dữ liệu ra đầu ra chuẩn. Dấu ; kết thúc câu lệnh. "..." là chuỗi ký tự, còn \'\\n\' xuống dòng. return 0 báo chương trình kết thúc bình thường.','<iostream> provides input/output facilities. int main() is the entry point. Braces enclose the function body. std::cout writes to standard output. A semicolon ends a statement. Double quotes enclose text, while \'\\n\' inserts a newline. return 0 indicates normal completion.')},
  {title:pair('Thử thay đổi','Make a change'),body:pair('Chạy ví dụ, đổi Hello thành tên của bạn rồi chạy lại. Giữ nguyên dấu ngoặc kép. Nếu bỏ dấu ;, xem thông báo biên dịch và sửa lại trước khi tiếp tục.','Run the example, replace Hello with your name, and run it again. Keep the quotation marks. Remove a semicolon once, read the compiler diagnostic, and restore it before continuing.')}
 ],example:example('hello','#include <iostream>\nint main() {\n    std::cout << "Hello, C++!" << \'\\n\';\n    return 0;\n}\n','','Hello, C++!\n'),
 quiz:{question:pair('Hàm nào là điểm bắt đầu của chương trình này?','Which function is the entry point?'),options:[pair('main','main'),pair('cout','cout'),pair('iostream','iostream')],answer:0,explain:pair('main là hàm bắt đầu thực thi; cout là đối tượng xuất dữ liệu.','Execution starts in main; cout is an output object.')},source:{book:0,page:3}},
 {id:'variables',title:pair('2. Biến và kiểu dữ liệu','2. Variables and types'),goal:pair('Khai báo, khởi tạo và cập nhật biến đúng kiểu.','Declare, initialize and update typed variables.'),sections:[
  {title:pair('Một tên cho một giá trị','A name for a value'),body:pair('Biến có tên, kiểu và giá trị. int count = 3; tạo biến số nguyên đã được khởi tạo. count = count + 2; tính giá trị bên phải trước rồi gán lại. Không đọc biến cục bộ chưa được khởi tạo.','A variable has a name, a type and a value. int count = 3; initializes an integer variable. count = count + 2; evaluates the right side before assigning it. Never read an uninitialized local variable.')},
  {title:pair('Chọn kiểu phù hợp','Choose an appropriate type'),body:pair('int dùng cho số nguyên có phạm vi vừa phải; long long cho số nguyên lớn hơn; double cho số thực gần đúng; char cho một ký tự; bool cho true/false. Kích thước int phụ thuộc hệ thống; long long có ít nhất 64 bit. Dùng const khi giá trị không cần thay đổi.','Use int for moderate integers, long long for larger integers, double for approximate real numbers, char for a character and bool for true/false. The size of int is implementation dependent; long long has at least 64 bits. Use const for values that should not change.')},
  {title:pair('Phạm vi và tràn số','Range and overflow'),body:pair('Kiểu lớn ở biến nhận không tự sửa phép nhân kiểu nhỏ. Nếu a và b là int lớn, dùng 1LL * a * b để phép nhân diễn ra bằng long long. Tràn số nguyên có dấu là hành vi không xác định.','A large destination type does not fix multiplication performed in a smaller type. For large int operands, use 1LL * a * b to multiply in long long. Signed integer overflow is undefined behavior.')}
 ],example:example('variables','#include <iostream>\nint main() {\n    int count = 3;\n    count = count + 2;\n    const long long unitPrice = 1000000000LL;\n    std::cout << count << \' \' << count * unitPrice << \'\\n\';\n}\n','','5 5000000000\n'),quiz:{question:pair('Sau int x = 3; x = x + 2; giá trị x là gì?','After int x = 3; x = x + 2;, what is x?'),options:[pair('3','3'),pair('5','5'),pair('Không xác định','Undefined')],answer:1,explain:pair('Vế phải là 3 + 2; kết quả 5 được gán lại cho x.','The right side is 3 + 2; its result, 5, is assigned to x.')},source:{book:0,page:7}},
 {id:'io',title:pair('3. Nhập và xuất','3. Input and output'),goal:pair('Đọc dữ liệu bằng cin và xuất đúng định dạng.','Read with cin and write the exact required format.'),sections:[
 {title:pair('Dữ liệu đi vào chương trình','Getting data into a program'),body:pair('std::cin >> a >> b đọc hai giá trị và bỏ qua khoảng trắng giữa chúng. Dữ liệu có thể nằm trên một hoặc nhiều dòng. Nếu đọc thất bại, không tiếp tục tính bằng giá trị chưa hợp lệ: kiểm tra if (!(std::cin >> a >> b)) return 0;.','std::cin >> a >> b reads two values, skipping whitespace between them. The values can be on one line or several. If extraction fails, do not calculate with invalid values: check if (!(std::cin >> a >> b)) return 0;.')},
 {title:pair('Định dạng là một phần của đáp án','Formatting is part of the answer'),body:pair('Trong bài chấm tự động, chỉ in thứ đề yêu cầu. Không in thêm "Nhap a:". Dùng \' \' để ngăn hai số và \'\\n\' để kết thúc dòng. Đầu vào và đầu ra là hai kênh khác nhau.','For automatically judged tasks, print only what the statement requests. Do not add prompts such as "Enter a:". Separate values with a space and finish a line with \'\\n\'. Input and output are separate streams.')}
 ],example:example('sum','#include <iostream>\nint main() {\n    long long a, b;\n    if (!(std::cin >> a >> b)) return 0;\n    std::cout << a + b << \'\\n\';\n}\n','7 -2\n','5\n'),quiz:{question:pair('Đề yêu cầu chỉ in tổng. Nên in gì khi đầu vào là 2 3?','The task asks for only the sum. What should input 2 3 produce?'),options:[pair('Tong = 5','Sum = 5'),pair('5','5'),pair('Nhap a: 2 3','Enter a: 2 3')],answer:1,explain:pair('Không thêm lời nhắc hoặc nhãn mà đề không yêu cầu.','Do not add prompts or labels that the task does not request.')},source:{book:0,page:10}},
 {id:'arithmetic',title:pair('4. Biểu thức và phép chia','4. Expressions and division'),goal:pair('Phân biệt chia nguyên, chia thực và phép dư.','Distinguish integer division, floating division and remainder.'),sections:[
 {title:pair('Kiểu của toán hạng quyết định phép chia','Operand types determine division'),body:pair('7 / 2 bằng 3 vì cả hai toán hạng đều nguyên. 7.0 / 2 bằng 3.5. Gán 7 / 2 vào double vẫn nhận 3.0 vì phép chia nguyên đã xảy ra. Với số âm, phép chia nguyên cắt phần lẻ về 0. Không chia cho 0.','7 / 2 is 3 because both operands are integers. 7.0 / 2 is 3.5. Assigning 7 / 2 to a double still yields 3.0 because integer division already occurred. For negative integers, division truncates toward zero. Never divide by zero.')},
 {title:pair('Phép dư và thứ tự tính','Remainder and precedence'),body:pair('a % b cho phần dư của phép chia nguyên. Với a không âm và b dương: a = (a / b) * b + a % b. Nhân, chia và dư có ưu tiên cao hơn cộng/trừ. Dùng ngoặc để thể hiện rõ ý định: (a + b) / 2.0.','a % b gives the integer remainder. For nonnegative a and positive b: a = (a / b) * b + a % b. Multiplication, division and remainder precede addition and subtraction. Use parentheses to make intent clear: (a + b) / 2.0.')}
 ],example:example('division','#include <iostream>\nint main() {\n    std::cout << 7 / 2 << \' \' << 7 % 2 << \' \' << 7.0 / 2 << \'\\n\';\n}\n','','3 1 3.5\n'),quiz:{question:pair('Biểu thức nào cho trung bình thực của hai số nguyên a, b nhỏ?','Which computes a real-valued average of small integers a and b?'),options:[pair('(a + b) / 2','(a + b) / 2'),pair('(a + b) / 2.0','(a + b) / 2.0'),pair('a + b / 2','a + b / 2')],answer:1,explain:pair('2.0 làm phép chia thực; ngoặc buộc cộng trước.','2.0 requests floating division; parentheses force addition first.')},source:{book:0,page:8}},
 {id:'debug',title:pair('5. Đọc lỗi và tự kiểm thử','5. Diagnostics and self-testing'),goal:pair('Phân biệt lỗi cú pháp, lỗi chạy và lỗi kết quả.','Distinguish compilation, runtime and wrong-answer failures.'),sections:[
 {title:pair('Ba loại vấn đề','Three kinds of failure'),body:pair('Thiếu dấu ; thường gây lỗi biên dịch. Chia nguyên cho 0 có thể khiến chương trình lỗi lúc chạy. Tính diện tích bằng a + b có thể chạy bình thường nhưng sai đáp án. Sửa lỗi biên dịch đầu tiên trước; các lỗi tiếp theo đôi khi chỉ là hệ quả.','A missing semicolon commonly causes a compilation error. Integer division by zero can fail at runtime. Using a + b for area may run but produce the wrong answer. Fix the first compiler diagnostic first; later diagnostics can be consequences.')},
 {title:pair('Chọn test có mục đích','Choose tests deliberately'),body:pair('Với bài cộng hai số, thử số dương, số âm, 0, hai số trái dấu và giới hạn lớn nhất. Tự tính đáp án trước khi chạy. Test đạt chỉ chứng minh các trường hợp đã thử; không chứng minh chương trình đúng cho mọi đầu vào.','For a sum task, test positives, negatives, zero, opposite signs and the largest allowed values. Work out the expected answer before running. Passing tests verifies the cases tried; it does not prove correctness for every input.')}
 ],example:example('check','#include <iostream>\nint main() {\n    long long a = 1000000000LL, b = 1000000000LL;\n    std::cout << a * b << \'\\n\';\n}\n','','1000000000000000000\n'),quiz:{question:pair('Chương trình chạy nhưng in diện tích sai: đây thường là gì?','The program runs but prints an incorrect area. What is this?'),options:[pair('Lỗi kết quả / logic','Wrong answer / logic error'),pair('Luôn là lỗi biên dịch','Always a compilation error'),pair('Đã thành công','Success')],answer:0,explain:pair('Chạy được không có nghĩa là tính đúng.','Successful execution does not imply a correct calculation.')},source:{book:0,page:3}}
 ];
 const exercises=[
 {id:'sum',lesson:'io',title:pair('A. Tổng hai số nguyên','A. Sum of two integers'),statement:pair('Đọc hai số nguyên a, b trong [-10^9, 10^9]. In tổng a + b trên một dòng.','Read integers a and b in [-10^9, 10^9]. Print a + b on one line.'),tests:[['2 3\n','5\n'],['0 0\n','0\n'],['-7 -4\n','-11\n'],['9 -9\n','0\n'],['1000000000 1000000000\n','2000000000\n']],solution:'#include <iostream>\nint main(){long long a,b;if(std::cin>>a>>b)std::cout<<a+b<<\'\\n\';}\n'},
 {id:'rectangle',lesson:'variables',title:pair('B. Hình chữ nhật','B. Rectangle'),statement:pair('Đọc chiều dài a và chiều rộng b là số nguyên, 1 ≤ a,b ≤ 10^9. In chu vi rồi diện tích, cách nhau một dấu cách.','Read integer side lengths a and b, 1 ≤ a,b ≤ 10^9. Print the perimeter followed by the area, separated by one space.'),tests:[['3 4\n','14 12\n'],['1 1\n','4 1\n'],['1 1000000000\n','2000000002 1000000000\n'],['1000000000 1000000000\n','4000000000 1000000000000000000\n']],solution:'#include <iostream>\nint main(){long long a,b;if(std::cin>>a>>b)std::cout<<2*(a+b)<<\' \'<<a*b<<\'\\n\';}\n'},
 {id:'minutes',lesson:'arithmetic',title:pair('C. Đổi phút thành giờ','C. Minutes to hours'),statement:pair('Đọc số phút n, 0 ≤ n ≤ 10^9. In số giờ nguyên và số phút còn lại, cách nhau một dấu cách. Một giờ có 60 phút.','Read minutes n, 0 ≤ n ≤ 10^9. Print the whole hours and remaining minutes, separated by one space. One hour has 60 minutes.'),tests:[['125\n','2 5\n'],['0\n','0 0\n'],['59\n','0 59\n'],['60\n','1 0\n'],['1000000000\n','16666666 40\n']],solution:'#include <iostream>\nint main(){long long n;if(std::cin>>n)std::cout<<n/60<<\' \'<<n%60<<\'\\n\';}\n'}
 ];
 const hints={sum:[pair('Cần đọc đúng hai giá trị trước khi tính.','Read both values before calculating.'),pair('Tổng là a + b; không in thêm nhãn.','The result is a + b; do not print a label.'),pair('Dùng long long, đọc a và b bằng cin rồi xuất a + b và xuống dòng.','Use long long, read a and b with cin, then output a + b and a newline.')],rectangle:[pair('Có hai kết quả cần in, theo đúng thứ tự.','Print two results in the specified order.'),pair('Chu vi = 2 × (a + b); diện tích = a × b.','Perimeter = 2 × (a + b); area = a × b.'),pair('Đọc a, b vào long long để tích tới 10^18 không tràn; in hai công thức cách nhau một dấu cách.','Read a and b as long long to hold products up to 10^18; print both expressions separated by a space.')],minutes:[pair('Tách n thành các nhóm 60 phút và phần còn lại.','Separate n into groups of 60 minutes and a remainder.'),pair('Chia nguyên cho số giờ; phép dư cho số phút còn lại.','Integer division gives hours; remainder gives minutes left.'),pair('In n / 60 rồi n % 60, ngăn bằng một dấu cách.','Print n / 60 followed by n % 60, separated by a space.')]};
 for(const e of exercises)e.hints=hints[e.id];
 // Each chapter is usable offline: explanation, runnable example, check and practice.
 lessons.forEach(l=>l.chapterId='start');
 const program=(headers,body)=>headers.map(h=>'#include <'+h+'>').join('\n')+'\nint main() {\n'+body+'\n}\n';
 function add(chapterId,id,vi,en,goalVi,goalEn,sections,headers,body,input,output,qVi,qEn,options,answer,whyVi,whyEn){
  lessons.push({id,chapterId,title:pair(vi,en),goal:pair(goalVi,goalEn),sections:sections.map(([v,e,bv,be])=>({title:pair(v,e),body:pair(bv,be)})),example:example(id,program(headers,body),input,output),quiz:{question:pair(qVi,qEn),options:options.map(([v,e])=>pair(v,e)),answer,explain:pair(whyVi,whyEn)}});
 }
 add('flow','conditions','Rẽ nhánh và biểu thức logic','Branches and logical expressions','Chọn đúng nhánh và xử lý trường hợp bằng nhau.','Choose the correct branch and handle equality.',[
 ['Điều kiện','Conditions','`if` thực hiện một khối khi điều kiện đúng; `else` là nhánh còn lại. Dùng == để so sánh, không dùng =. Các phép <, <=, >, >= trả về bool. Đặt dấu ngoặc nhọn kể cả khi nhánh chỉ có một lệnh để tránh gắn else nhầm.','An if statement executes a block when its condition is true; else handles the other case. Use == for comparison, not assignment. Comparisons produce bool. Braces prevent an else from attaching to the wrong if.'],
 ['Kết hợp và biên','Combining conditions and boundaries','`&&` yêu cầu cả hai vế đúng; `||` chỉ cần một vế đúng; `!` đảo giá trị. C++ đánh giá ngắn mạch từ trái sang phải. Kiểm tra mẫu số khác 0 trước phép chia. Thử nhỏ hơn, bằng và lớn hơn ngưỡng.','Logical AND requires both operands, OR requires at least one, and NOT negates a value. Evaluation short-circuits from left to right. Check a denominator before dividing. Test values below, at and above each threshold.']
 ],['iostream'],'    int x; if (!(std::cin >> x)) return 0;\n    if (x < 0) std::cout << "NEGATIVE\\n";\n    else if (x == 0) std::cout << "ZERO\\n";\n    else std::cout << "POSITIVE\\n";','0\n','ZERO\n','Điều kiện nào kiểm tra x thuộc [1, 10]?','Which condition checks x in [1, 10]?', [['1 <= x && x <= 10','1 <= x && x <= 10'],['1 <= x <= 10','1 <= x <= 10'],['x < 1 || x > 10','x < 1 || x > 10']],0,'Phải kết hợp hai phép so sánh bằng &&; C++ không hiểu chuỗi so sánh theo ký hiệu toán học.','Combine two comparisons with &&; chained comparisons do not have their mathematical meaning in C++.');
 add('flow','loops','Vòng lặp và bất biến','Loops and invariants','Viết vòng lặp kết thúc và tránh lệch một đơn vị.','Write terminating loops and avoid off-by-one errors.',[
 ['Đếm và tích lũy','Counting and accumulation','`for` gồm khởi tạo, điều kiện và cập nhật. Với n phần tử đánh số từ 0, dùng i < n. Khởi tạo tổng bằng 0 trước vòng lặp. Sau k bước, tổng phải đúng bằng tổng k phần tử đã xử lý: đó là bất biến để tự kiểm tra.','A for loop has initialization, condition and update. For n zero-based elements, use i < n. Initialize a sum to zero. After k iterations it should equal the sum of the k processed elements; this invariant helps check correctness.'],
 ['Chọn kiểu lặp','Choosing a loop','`while` phù hợp khi chưa biết số lần lặp, còn do-while luôn chạy ít nhất một lần. break kết thúc vòng gần nhất; continue bỏ phần còn lại của lượt hiện tại. Mỗi lượt phải tiến về điều kiện dừng; thử n = 0 và n = 1.','Use while when the iteration count is unknown; do-while runs at least once. Break exits the nearest loop and continue skips the rest of an iteration. Ensure progress toward termination and test n = 0 and n = 1.']
 ],['iostream'],'    int n; if (!(std::cin >> n) || n < 0 || n > 1000000) return 0;\n    long long sum = 0;\n    for (int i = 1; i <= n; ++i) sum += i;\n    std::cout << sum << "\\n";','5\n','15\n','Vòng for (int i=0; i<n; ++i) chạy mấy lần khi n=0?','How many iterations occur when n=0?', [['0','0'],['1','1'],['Vô hạn','Forever']],0,'Điều kiện sai ngay ở lần kiểm tra đầu tiên.','The condition is false at the first check.');
 add('flow','nested-loops','Vòng lặp lồng và độ phức tạp','Nested loops and complexity','Đếm số thao tác trước khi chọn thuật toán.','Estimate operation counts before choosing an algorithm.',[
 ['Hai chiều','Two dimensions','Mỗi lượt vòng ngoài thực hiện toàn bộ vòng trong. Hai vòng chạy n và m lượt tạo n × m thao tác. Khi duyệt bảng, giữ rõ biến hàng và cột. Không tự ý thay biến đếm vòng ngoài trong thân vòng trong.','Each outer iteration executes the entire inner loop. Loops of n and m iterations perform n times m operations. Keep row and column indices distinct when traversing a table, and do not change the outer counter inside the inner loop.'],
 ['Ước lượng','Estimating work','O(n²) tăng nhanh hơn O(n): khi n gấp đôi, số cặp tăng khoảng bốn lần. Với n = 100000, duyệt mọi cặp thường quá chậm. Dùng ví dụ nhỏ để đối chiếu kết quả rồi mới thử giới hạn lớn.','Quadratic work grows faster than linear work: doubling n roughly quadruples the number of pairs. Enumerating all pairs of 100000 items is usually too costly. Compare a small hand-worked example before testing large limits.']
 ],['iostream'],'    int n; if (!(std::cin >> n) || n < 0 || n > 20) return 0;\n    for (int r=1; r<=n; ++r) {\n        for(int c=0; c<r; ++c) std::cout << "*";\n        std::cout << "\\n";\n    }','3\n','*\n**\n***\n','Hai vòng độc lập đều chạy n lượt có độ phức tạp nào?','Two nested loops each run n iterations. What is the complexity?', [['O(n)','O(n)'],['O(n²)','O(n²)'],['O(1)','O(1)']],1,'Mỗi lượt ngoài thực hiện n lượt trong, tổng n × n.','Each of n outer iterations performs n inner iterations.');
 add('functions','function-values','Hàm và truyền tham trị','Functions and value parameters','Chia chương trình thành hàm có hợp đồng rõ ràng.','Split a program into functions with clear contracts.',[
 ['Đầu vào và kết quả','Inputs and results','Hàm đặt tên cho một thao tác. Khai báo kiểu trả về, tên và danh sách tham số; return trả kết quả. Viết tiền điều kiện và điều chương trình bảo đảm sau khi gọi. Mỗi hàm nên làm một việc để dễ kiểm thử.','A function names an operation. Specify its return type, name and parameters; return provides its result. State preconditions and postconditions. A function with one clear responsibility is easier to test and reuse.'],
 ['Bản sao','Copies','Tham số kiểu int hoặc long long truyền theo giá trị là bản sao. Sửa tham số không đổi biến bên ngoài. Biến cục bộ chỉ sống trong lần gọi. Không trả con trỏ hoặc tham chiếu tới biến cục bộ đã hết thời gian sống.','A value parameter is a copy. Changing an int or long long parameter does not change the caller variable. Local variables live only during the call. Never return a pointer or reference to an expired local variable.']
 ],['iostream'],'    auto square = [](long long x) { return x*x; };\n    long long n; if (!(std::cin >> n) || n < -1000000000LL || n > 1000000000LL) return 0;\n    std::cout << square(n) << "\\n";','-12\n','144\n','Sửa một tham số int truyền theo giá trị có đổi biến gọi không?','Does changing an int value parameter change the caller variable?', [['Có','Yes'],['Không','No']],1,'Hàm sửa bản sao, không sửa đối tượng của bên gọi.','The function modifies a copy, not the caller object.');
 add('functions','references-tests','Tham chiếu và kiểm thử hàm','References and function tests','Phân biệt đọc dữ liệu với thay đổi dữ liệu.','Distinguish reading data from mutating it.',[
 ['Tham chiếu','References','Tham số T& là tên khác của đối tượng bên gọi, nên thay đổi được giữ lại. const T& cho phép đọc mà tránh sao chép đối tượng lớn. Chỉ dùng tham chiếu thay đổi khi hợp đồng hàm thực sự cần sửa đầu vào.','A T& parameter aliases the caller object, so mutations persist. A const T& allows reading without copying a large object. Use mutable references only when modifying the input is part of the function contract.'],
 ['Kiểm thử nhỏ','Small tests','Chọn test bình thường, biên và trường hợp đặc biệt. Với hàm đổi chỗ, thử hai số khác nhau, bằng nhau và số âm. assert kiểm tra một giả định trong chế độ có bật khẳng định; không dùng assert thay cho kiểm tra đầu vào của người dùng.','Test ordinary, boundary and special cases. For swapping, try distinct values, equal values and negatives. Assert checks an assumption when assertions are enabled; it is not a substitute for validating user input.']
 ],['iostream','cassert'],'    auto swapValues = [](int& a, int& b) { int t=a; a=b; b=t; };\n    int a=2,b=7; swapValues(a,b); assert(a==7 && b==2);\n    std::cout << a << " " << b << "\\n";','','7 2\n','Kiểu nào phù hợp để đọc vector lớn mà không sao chép?','Which parameter reads a large vector without copying?', [['const std::vector<int>&','const std::vector<int>&'],['std::vector<int>','std::vector<int>']],0,'Tham chiếu const tránh sao chép và ngăn sửa qua tham số.','A const reference avoids a copy and prevents mutation through that parameter.');
 add('functions','recursion','Đệ quy và điều kiện dừng','Recursion and base cases','Theo dõi lời gọi và giới hạn độ sâu đệ quy.','Trace calls and control recursion depth.',[
 ['Bài toán nhỏ hơn','A smaller problem','Hàm đệ quy gọi lại chính nó với bài toán nhỏ hơn. Luôn viết điều kiện dừng trước. Với gcd(a,b), khi b = 0 trả a; ngược lại gọi gcd(b,a%b). Phần dư nhỏ hơn b khi các số không âm nên lời gọi tiến tới dừng.','A recursive function calls itself on a smaller problem. Write the base case first. For gcd(a,b), return a when b is zero; otherwise call gcd(b,a%b). With nonnegative inputs the remainder is smaller than b, ensuring progress.'],
 ['Ngăn xếp','The call stack','Mỗi lời gọi giữ tham số và trạng thái trên ngăn xếp. Đệ quy tuyến tính rất sâu có thể tràn ngăn xếp dù thuật toán đúng. Khi độ sâu phụ thuộc n lớn, cân nhắc vòng lặp hoặc ngăn xếp tường minh. Truy vết một ví dụ bằng tay.','Each call stores parameters and state on the call stack. Deep linear recursion can overflow it even if the algorithm is logically correct. For depth proportional to a large n, use a loop or an explicit stack. Trace a small example by hand.']
 ],['iostream','functional'],'    std::function<long long(long long,long long)> gcd = [&](long long a,long long b)->long long { return b==0 ? a : gcd(b,a%b); };\n    long long a,b; if (!(std::cin>>a>>b) || a<0 || b<0) return 0;\n    std::cout << gcd(a,b) << "\\n";','48 18\n','6\n','Điều gì bắt buộc để đệ quy kết thúc?','What is required for recursion to terminate?', [['Chỉ cần gọi chính nó','Calling itself is sufficient'],['Có trường hợp dừng và tiến về trường hợp đó','A base case and progress toward it']],1,'Điều kiện dừng không có tác dụng nếu lời gọi không tiến gần nó.','A base case is ineffective if calls do not approach it.');
 add('data','vectors','Mảng và vector an toàn','Arrays and safe vectors','Lưu nhiều giá trị và truy cập trong giới hạn.','Store multiple values and stay within bounds.',[
 ['Kích thước và chỉ số','Size and indices','Vector quản lý một dãy liên tiếp có kích thước thay đổi. Tạo vector<int> a(n) để có n phần tử, chỉ số hợp lệ từ 0 tới n-1. reserve chỉ cấp dung lượng, không tạo phần tử. push_back thêm một phần tử vào cuối.','A vector manages a contiguous sequence with a variable size. A vector<int> a(n) contains n elements indexed from 0 to n-1. Reserve changes capacity, not size. Push_back appends an element to the sequence.'],
 ['Duyệt an toàn','Safe traversal','Dùng vòng lặp theo phạm vi khi không cần chỉ số. Không đọc a[0] nếu vector rỗng; at kiểm tra biên và ném ngoại lệ khi sai. Phép thêm có thể cấp lại vùng nhớ, làm mất hiệu lực con trỏ hoặc iterator đang giữ.','Use a range-based loop when indices are unnecessary. Do not access a[0] in an empty vector; at checks bounds and throws on invalid access. Growth may reallocate storage and invalidate existing pointers or iterators.']
 ],['iostream','vector'],'    int n; if (!(std::cin>>n) || n<0 || n>100000) return 0;\n    std::vector<int> a(n); long long sum=0;\n    for(int& x:a) { if(!(std::cin>>x)) return 0; sum+=x; }\n    std::cout<<sum<<"\\n";','4\n2 -3 7 1\n','7\n','reserve(10) có tạo 10 phần tử không?','Does reserve(10) create ten elements?', [['Có','Yes'],['Không','No']],1,'reserve thay đổi capacity; resize mới thay đổi size.','Reserve changes capacity; resize changes size.');
 add('data','strings','Chuỗi và xử lý dòng','Strings and line input','Đọc cả dòng và xử lý ký tự đúng cách.','Read whole lines and process characters safely.',[
 ['Token và dòng','Tokens and lines','cin >> s dừng ở khoảng trắng; getline đọc tới ký tự xuống dòng. Khi đổi từ >> sang getline, xử lý dấu xuống dòng còn lại bằng ignore phù hợp. Không dùng std::ws nếu cần giữ dòng rỗng hoặc khoảng trắng đầu dòng.','Extraction with >> stops at whitespace; getline reads to a newline. When switching from formatted extraction, consume the leftover newline appropriately. Do not use std::ws when empty lines or leading spaces must be preserved.'],
 ['Ký tự và bảng mã','Characters and encoding','std::string lưu byte, không tự hiểu ký tự Unicode. Các ví dụ chỉ đếm chữ ASCII; tiếng Việt UTF-8 có thể cần nhiều byte cho một ký tự. Khi gọi isalpha hoặc toupper, chuyển sang unsigned char trước để tránh hành vi không xác định.','A std::string stores bytes, not Unicode characters. These examples count ASCII letters; a Vietnamese UTF-8 character can occupy multiple bytes. Cast to unsigned char before passing a char to isalpha or toupper to avoid undefined behavior.']
 ],['iostream','string'],'    std::string s; if(!std::getline(std::cin,s)) return 0;\n    int count=0; for(unsigned char c:s) if((c>=\'a\'&&c<=\'z\')||(c>=\'A\'&&c<=\'Z\')) ++count;\n    std::cout<<count<<"\\n";','Hello C++ 17\n','6\n','Hàm nào đọc một dòng có khoảng trắng?','Which reads a line containing spaces?', [['std::getline','std::getline'],['cin >> s','cin >> s']],0,'getline giữ các khoảng trắng trong dòng, khác phép đọc token.','Getline preserves spaces within the line, unlike token extraction.');
 add('data','prefix-sums','Tổng tiền tố và ma trận','Prefix sums and matrices','Trả lời tổng đoạn sau một lần tiền xử lý.','Answer range sums after preprocessing.',[
 ['Tổng nửa mở','Half-open sums','Đặt p[0]=0 và p[i+1]=p[i]+a[i]. Khi đó tổng các chỉ số [l,r) bằng p[r]-p[l]. Dùng vector n+1 phần tử và long long cho tổng lớn. Quy ước nửa mở giúp xử lý đoạn rỗng một cách nhất quán.','Set p[0]=0 and p[i+1]=p[i]+a[i]. The sum over indices [l,r) is p[r]-p[l]. Allocate n+1 entries and use long long for large sums. Half-open ranges handle empty intervals consistently.'],
 ['Bảng hai chiều','Two-dimensional tables','Ma trận có thể lưu bằng vector<vector<int>> với số hàng và cột rõ ràng. Mỗi chiều có biên riêng. Tổng tiền tố một chiều xây O(n), mỗi truy vấn O(1); đổi một phần tử sẽ làm các tổng phía sau không còn đúng.','A matrix can use vector<vector<int>> with explicit row and column counts. Each dimension has its own bounds. One-dimensional prefix sums take O(n) to build and O(1) per query; changing an element invalidates later prefix values.']
 ],['iostream','vector'],'    std::vector<int> a{2,4,-1,5}; std::vector<long long> p(a.size()+1);\n    for(std::size_t i=0;i<a.size();++i) p[i+1]=p[i]+a[i];\n    std::cout<<p[4]-p[1]<<"\\n";','','8\n','Tổng a[l..r) dùng công thức nào?','How do you sum a[l..r)?', [['p[r] - p[l]','p[r] - p[l]'],['p[r] + p[l]','p[r] + p[l]']],0,'p[l] loại bỏ đúng l phần tử trước đoạn cần tính.','Subtracting p[l] removes the l elements preceding the range.');
 add('memory','pointers','Con trỏ và thời gian sống','Pointers and lifetimes','Hiểu địa chỉ, giải tham chiếu và nullptr.','Understand addresses, dereferencing and nullptr.',[
 ['Địa chỉ và đối tượng','Addresses and objects','Toán tử & lấy địa chỉ; int* giữ địa chỉ một int. *p truy cập đối tượng được trỏ tới. Con trỏ phải trỏ tới đối tượng còn sống trước khi giải tham chiếu. nullptr biểu thị không trỏ tới đối tượng nào.','The address-of operator obtains an address; int* stores the address of an int. Dereferencing accesses that object. A pointer must refer to a live object before dereferencing. Nullptr means that no object is referenced.'],
 ['Con trỏ treo','Dangling pointers','Khi đối tượng bị hủy, địa chỉ cũ không còn hợp lệ dù con trỏ chưa bằng nullptr. Không trả địa chỉ biến cục bộ. Không thực hiện số học con trỏ ra ngoài cùng một mảng; con trỏ ngay sau mảng chỉ dùng so sánh, không được đọc.','After destruction, an old address is invalid even if the pointer is not null. Never return a local variable address. Pointer arithmetic must stay within the same array or its one-past position; that one-past pointer must not be dereferenced.']
 ],['iostream'],'    int value=10; int* p=&value;\n    if(p) *p=25;\n    std::cout<<value<<"\\n";','','25\n','Có thể đọc *p khi p == nullptr không?','Can you read *p when p is nullptr?', [['Có','Yes'],['Không','No']],1,'Không có đối tượng hợp lệ để truy cập.','There is no valid object to access.');
 add('memory','raii','RAII và con trỏ thông minh','RAII and smart pointers','Quản lý tài nguyên bằng thời gian sống đối tượng.','Manage resources through object lifetimes.',[
 ['Sở hữu','Ownership','new cấp phát và delete giải phóng, nhưng bỏ sót hoặc giải phóng hai lần đều nguy hiểm. RAII gắn tài nguyên với một đối tượng sở hữu: khi rời phạm vi, destructor giải phóng tự động. Ưu tiên vector và string cho dữ liệu thông thường.','New allocates and delete releases memory, but missing a release or releasing twice is dangerous. RAII ties a resource to an owner whose destructor releases it on scope exit. Prefer vector and string for ordinary data storage.'],
 ['Một chủ sở hữu','One owner','unique_ptr không sao chép được vì chỉ có một chủ sở hữu. make_unique tạo nó an toàn; std::move chuyển quyền sở hữu, không nhân đôi đối tượng. shared_ptr chỉ nên dùng khi thực sự cần đồng sở hữu; vòng tham chiếu cần weak_ptr.','A unique_ptr cannot be copied because ownership is exclusive. Make_unique creates one safely; std::move transfers ownership rather than duplicating the object. Use shared_ptr only for genuine shared ownership and weak_ptr to break ownership cycles.']
 ],['iostream','memory','utility'],'    auto a=std::make_unique<int>(42);\n    auto b=std::move(a);\n    std::cout<<(a==nullptr)<<" "<<*b<<"\\n";','','1 42\n','Sau khi chuyển unique_ptr a sang b, ai sở hữu dữ liệu?','After moving unique_ptr a to b, who owns the data?', [['b','b'],['Cả hai','Both']],0,'b nhận quyền sở hữu và a trở thành rỗng.','b owns the object and a becomes empty.');
 add('memory','memory-safety','Lỗi bộ nhớ và cách phòng tránh','Memory errors and prevention','Nhận diện rò rỉ, vượt biên và dùng sau giải phóng.','Recognize leaks, bounds errors and use-after-free.',[
 ['Các lỗi thường gặp','Common failures','Đọc vượt biên, dùng sau delete và đọc biến chưa khởi tạo có thể cho kết quả thất thường. Một lần chạy không lỗi không chứng minh an toàn. Giữ quyền sở hữu rõ ràng, khởi tạo dữ liệu và kiểm tra chỉ số trước khi truy cập.','Out-of-bounds reads, use-after-delete and uninitialized reads can produce inconsistent results. A successful run does not establish safety. Keep ownership explicit, initialize data and validate indices before accessing storage.'],
 ['Kiểm tra có hệ thống','Systematic checks','Dùng at khi học để nhận lỗi biên rõ ràng. Kiểm thử dãy rỗng, một phần tử và chỉ số bằng size. Trình biên dịch hỗ trợ có thể chạy AddressSanitizer để phát hiện nhiều lỗi động; công cụ không thay thế thiết kế quyền sở hữu đúng.','Use at while learning for explicit bounds failures. Test an empty sequence, one element and an index equal to size. When supported, AddressSanitizer detects many dynamic memory errors, but tools do not replace sound ownership design.']
 ],['iostream','vector','stdexcept'],'    std::vector<int> a{4,8};\n    try { std::cout<<a.at(2); }\n    catch(const std::out_of_range&) { std::cout<<"OUT_OF_RANGE\\n"; }','','OUT_OF_RANGE\n','Chỉ số size() có hợp lệ để đọc phần tử không?','Is size() a valid element index?', [['Không','No'],['Có','Yes']],0,'Chỉ số lớn nhất là size()-1 nếu dãy không rỗng.','For a nonempty sequence the last index is size()-1.');
 add('objects','structs','Struct và mô hình dữ liệu','Structs and data models','Gom dữ liệu liên quan thành một kiểu có nghĩa.','Group related data into a meaningful type.',[
 ['Một bản ghi','A record','Struct ghép nhiều thành viên thành một đối tượng. Truy cập bằng dấu chấm; khởi tạo đủ trường để tránh giá trị không xác định. Mặc định thành viên struct là public. Tên trường nên mô tả ý nghĩa thay vì chỉ a, b, c.','A struct combines members into one object. Use dot access and initialize every field to avoid indeterminate values. Struct members are public by default. Give fields descriptive names rather than unrelated letters.'],
 ['Tách dữ liệu và trình bày','Separate data from presentation','Một kiểu Student có thể chứa tên và điểm; vector<Student> lưu nhiều bản ghi. Hàm tính trung bình không nên tự đọc bàn phím hoặc in thông báo, nhờ đó có thể dùng lại trong giao diện và kiểm thử riêng.','A Student type can contain a name and score; vector<Student> stores multiple records. A function computing an average should not read the keyboard or print prompts, allowing reuse in a UI and independent testing.']
 ],['iostream','string'],'    struct Student { std::string name; int score; };\n    Student s{"An",85};\n    std::cout<<s.name<<" "<<s.score<<"\\n";','','An 85\n','Thành viên struct mặc định có mức truy cập nào?','What is the default access in a struct?', [['public','public'],['private','private']],0,'Struct mặc định public; class mặc định private.','Struct defaults to public; class defaults to private.');
 add('objects','classes','Class, constructor và đóng gói','Classes, constructors and encapsulation','Bảo vệ bất biến dữ liệu qua giao diện công khai.','Protect data invariants through a public interface.',[
 ['Khởi tạo hợp lệ','Valid construction','Constructor tạo trạng thái ban đầu của đối tượng. Dùng danh sách khởi tạo thành viên. Đặt dữ liệu cần bảo vệ ở private và cung cấp hàm public thực hiện thao tác hợp lệ. Class mặc định private; struct mặc định public.','A constructor establishes initial state. Use a member initializer list. Put protected state in private members and expose public operations that preserve valid states. Class defaults to private access, whereas struct defaults to public.'],
 ['Bất biến','Invariants','Ví dụ tài khoản không cho rút quá số dư. Hàm kiểm tra điều kiện trước khi sửa dữ liệu, trả kết quả thành công/thất bại. Hàm chỉ đọc nên đánh dấu const. Không trả tham chiếu thay đổi tới dữ liệu private nếu nó phá vỡ kiểm soát.','An account can reject withdrawals exceeding its balance. Check conditions before mutation and return success or failure. Mark read-only methods const. Do not expose mutable references to private data when that bypasses invariant checks.']
 ],['iostream'],'    class Counter { int value; public: explicit Counter(int v):value(v){} void add(){++value;} int get() const{return value;} };\n    Counter c(4); c.add(); std::cout<<c.get()<<"\\n";','','5\n','Hàm chỉ đọc đối tượng nên có từ khóa nào ở cuối khai báo?','Which qualifier belongs on a read-only member function?', [['const','const'],['delete','delete']],0,'const ngăn sửa thành viên thông thường thông qua this.','Const prevents modification of ordinary members through this.');
 add('objects','polymorphism','Kế thừa và đa hình','Inheritance and polymorphism','Gọi hành vi phù hợp qua giao diện lớp cơ sở.','Dispatch behavior through a base interface.',[
 ['Giao diện chung','A shared interface','Kế thừa public mô tả quan hệ là-một. Hàm virtual chọn phiên bản theo kiểu đối tượng thực khi gọi qua con trỏ hoặc tham chiếu cơ sở. override yêu cầu trình biên dịch kiểm tra việc ghi đè đúng chữ ký.','Public inheritance represents an is-a relationship. A virtual call through a base pointer or reference dispatches according to the actual object type. Override asks the compiler to verify that the signature really overrides a base method.'],
 ['Hủy và cắt lát','Destruction and slicing','Lớp cơ sở dùng để xóa đối tượng dẫn xuất cần destructor virtual. Truyền đối tượng dẫn xuất theo giá trị cơ sở gây cắt lát. Ưu tiên tham chiếu hoặc smart pointer. Không dùng kế thừa chỉ để tái sử dụng vài dòng code; cân nhắc chứa đối tượng.','A base class used to delete derived objects needs a virtual destructor. Passing a derived object by base value causes slicing. Prefer references or smart pointers. Do not inherit merely to reuse a few lines; consider composition instead.']
 ],['iostream'],'    struct Shape { virtual int area() const=0; virtual ~Shape()=default; };\n    struct Square:Shape { int side; explicit Square(int s):side(s){} int area() const override{return side*side;} };\n    Square s(4); const Shape& base=s; std::cout<<base.area()<<"\\n";','','16\n','Từ khóa nào giúp kiểm tra ghi đè đúng hàm virtual?','Which keyword checks a correct virtual override?', [['override','override'],['static','static']],0,'override bắt lỗi chữ ký không khớp ngay khi biên dịch.','Override catches mismatched signatures at compile time.');
 add('stl','sort-search','Sắp xếp và tìm kiếm nhị phân','Sorting and binary search','Dùng thư viện với đúng tiền điều kiện.','Use library algorithms with their preconditions.',[
 ['Sắp xếp','Sorting','std::sort nhận đoạn iterator [begin,end) và sắp xếp O(n log n). Hàm so sánh phải là thứ tự yếu nghiêm ngặt: comp(x,x) luôn false. Không dùng <= làm comparator. stable_sort giữ thứ tự tương đối của các phần tử tương đương.','Std::sort operates on [begin,end) in O(n log n). Its comparator must define a strict weak ordering: comp(x,x) is always false. Do not use <= as a comparator. Stable_sort preserves relative order among equivalent elements.'],
 ['Tìm vị trí','Finding positions','lower_bound trả phần tử đầu tiên không nhỏ hơn x, hoặc end nếu không có. Dãy phải được sắp hoặc phân hoạch đúng comparator. Kiểm tra iterator khác end trước khi đọc. upper_bound trả phần tử đầu tiên lớn hơn x.','Lower_bound returns the first element not less than x, or end if none exists. The range must be sorted or appropriately partitioned under the comparator. Check against end before dereferencing. Upper_bound returns the first element greater than x.']
 ],['iostream','vector','algorithm'],'    std::vector<int> a{7,2,4,2}; std::sort(a.begin(),a.end());\n    auto it=std::lower_bound(a.begin(),a.end(),4);\n    std::cout<<(it-a.begin())<<"\\n";','','2\n','lower_bound có thể dùng tùy ý trên dãy chưa sắp không?','Can lower_bound be used arbitrarily on an unsorted range?', [['Có','Yes'],['Không','No']],1,'Phải bảo đảm tiền điều kiện phân hoạch; dãy đã sắp là trường hợp thường dùng.','Its partitioning precondition must hold; a sorted range is the usual case.');
 add('stl','containers','Map, set, stack và queue','Maps, sets, stacks and queues','Chọn cấu trúc dữ liệu theo thao tác cần thực hiện.','Choose a container for the operations required.',[
 ['Khóa và tần suất','Keys and frequencies','set lưu khóa duy nhất có thứ tự; map ánh xạ khóa sang giá trị. map[key] có thể tạo khóa mới với giá trị mặc định. Dùng find khi chỉ muốn kiểm tra tồn tại. unordered_map có thời gian trung bình tốt nhưng không giữ thứ tự.','Set stores unique ordered keys; map associates keys with values. Map subscripting can insert a missing key with a default value. Use find for lookup without insertion. Unordered_map has good average lookup cost but does not preserve order.'],
 ['Thứ tự lấy ra','Removal order','stack dùng LIFO: phần tử vào sau ra trước. queue dùng FIFO: vào trước ra trước. Kiểm tra empty trước top hoặc front. priority_queue mặc định lấy phần tử lớn nhất; nó không phải hàng đợi FIFO và không giữ toàn bộ thứ tự duyệt.','A stack is LIFO and a queue is FIFO. Check empty before top or front. A default priority_queue exposes the largest element; it is neither FIFO nor a container supporting iteration in fully sorted order.']
 ],['iostream','map','string'],'    std::map<std::string,int> count;\n    for(const auto& word:{"red","blue","red"}) ++count[word];\n    for(const auto& item:count) std::cout<<item.first<<" "<<item.second<<"\\n";','','blue 1\nred 2\n','Cấu trúc nào lấy phần tử vào trước ra trước?','Which container removes the earliest inserted item first?', [['queue','queue'],['stack','stack']],0,'queue là FIFO; stack là LIFO.','Queue is FIFO; stack is LIFO.');
 add('stl','dp-graphs','Quy hoạch động và duyệt đồ thị','Dynamic programming and graph traversal','Xác định trạng thái, chuyển trạng thái và đánh dấu đã thăm.','Define states, transitions and visited markers.',[
 ['Lưu bài toán con','Store subproblem results','Quy hoạch động cần trạng thái rõ, cơ sở đúng và thứ tự tính để mọi phụ thuộc đã có. Ví dụ số cách leo n bậc với bước 1 hoặc 2: dp[0]=1, dp[1]=1, dp[i]=dp[i-1]+dp[i-2]. Dùng giới hạn nhỏ để tránh tràn số.','Dynamic programming needs precise states, valid bases and an evaluation order with dependencies already computed. For climbing n steps using moves of one or two, dp[0]=dp[1]=1 and dp[i]=dp[i-1]+dp[i-2]. Limit n to avoid overflow.'],
 ['Đồ thị','Graphs','Danh sách kề lưu hàng xóm của mỗi đỉnh. BFS dùng queue và tìm khoảng cách ít cạnh nhất trong đồ thị không trọng số. Đánh dấu ngay khi đưa đỉnh vào queue để tránh thêm lặp. DFS dùng ngăn xếp hoặc đệ quy; nhớ xử lý thành phần rời nhau.','An adjacency list stores each vertex neighbors. BFS uses a queue and finds minimum edge counts in unweighted graphs. Mark vertices when enqueuing to prevent duplicates. DFS uses recursion or a stack; handle disconnected components explicitly.']
 ],['iostream','vector'],'    int n; if(!(std::cin>>n)||n<0||n>90) return 0;\n    std::vector<long long> dp(n+2); dp[0]=1; dp[1]=1;\n    for(int i=2;i<=n;++i) dp[i]=dp[i-1]+dp[i-2];\n    std::cout<<dp[n]<<"\\n";','5\n','8\n','BFS tìm đường ít cạnh nhất trong loại đồ thị nào?','In which graph does BFS find minimum-edge paths?', [['Không trọng số','Unweighted'],['Mọi trọng số tùy ý','Arbitrary weights']],0,'BFS mở rộng theo từng lớp số cạnh, không theo tổng trọng số.','BFS expands by edge-count layers, not by total weight.');
 add('projects','project-statistics','Dự án: thống kê dữ liệu','Project: data statistics','Kết hợp nhập liệu, hàm và cấu trúc dữ liệu.','Combine input, functions and containers.',[
 ['Đặc tả trước khi viết','Specify before coding','Đọc n số, xuất nhỏ nhất, lớn nhất và tổng. Với n = 0, xuất EMPTY. Ghi rõ giới hạn n và giá trị để chọn kiểu tổng. Tách việc đọc, tính và xuất thành các bước; không trộn lời nhắc giao diện vào đầu ra chấm.','Read n values and output minimum, maximum and sum. For n = 0 output EMPTY. State bounds to choose a safe sum type. Separate reading, calculation and output; do not mix UI prompts into machine-checked output.'],
 ['Kiểm thử chấp nhận','Acceptance tests','Thử dãy rỗng, một số âm, mọi số bằng nhau, số tăng dần và tổng bằng 0. So sánh kết quả với phép tính tay. Khi mở rộng thêm trung bình, phải đặc tả số chữ số thập phân và không chia cho 0.','Test an empty list, one negative value, equal values, sorted values and a zero sum. Compare against hand calculations. If adding an average, specify decimal formatting and avoid division by zero.']
 ],['iostream','vector','algorithm','numeric'],'    int n; if(!(std::cin>>n)||n<0||n>100000) return 0;\n    std::vector<int> a(n); for(int& x:a) if(!(std::cin>>x)) return 0;\n    if(a.empty()) {std::cout<<"EMPTY\\n"; return 0;}\n    auto p=std::minmax_element(a.begin(),a.end());\n    std::cout<<*p.first<<" "<<*p.second<<" "<<std::accumulate(a.begin(),a.end(),0LL)<<"\\n";','4\n3 -2 8 1\n','-2 8 10\n','Tại sao tổng dùng giá trị khởi đầu 0LL?','Why initialize accumulate with 0LL?', [['Để cộng bằng long long','To accumulate in long long'],['Để tự sắp xếp','To sort automatically']],0,'Kiểu giá trị khởi đầu quyết định kiểu bộ tích lũy.','The initial value determines the accumulator type.');
 add('projects','project-commands','Dự án: bộ xử lý lệnh','Project: command processor','Xây giao thức lệnh xác định và xử lý lỗi.','Build a deterministic command protocol with error handling.',[
 ['Giao thức','Protocol','Đọc từng lệnh ADD x, GET hoặc END. ADD cộng x vào trạng thái; GET xuất trạng thái; END dừng. Lệnh không nhận dạng xuất ERROR rồi bỏ phần còn lại của dòng. Không thực thi chuỗi đầu vào như lệnh hệ thống.','Read ADD x, GET or END commands. ADD changes state, GET prints it and END stops. Unknown commands print ERROR and discard the rest of the line. Never execute input strings as system commands.'],
 ['Trạng thái và kiểm thử','State and tests','Trạng thái ban đầu bằng 0. Một test nên chứa nhiều lệnh để kiểm tra chuyển trạng thái; một test khác kết thúc ngay. Giới hạn độ lớn tổng và xử lý đọc tham số thất bại. Kết quả phải lặp lại được với cùng đầu vào.','The initial state is zero. Test multiple commands to verify state transitions, plus immediate termination. Bound the total and handle failed argument extraction. The same input should produce the same output every time.']
 ],['iostream','string','limits'],'    long long total=0; std::string cmd;\n    while(std::cin>>cmd) {\n        if(cmd=="END") break;\n        if(cmd=="GET") std::cout<<total<<"\\n";\n        else if(cmd=="ADD") {long long x; if(!(std::cin>>x)||x < -1000000||x > 1000000) return 0; if(total < -1000000000LL || total > 1000000000LL) return 0; total+=x;}\n        else {std::cout<<"ERROR\\n"; std::cin.ignore(std::numeric_limits<std::streamsize>::max(),\'\\n\');}\n    }','GET\nADD 7\nADD -2\nGET\nEND\n','0\n5\n','Một test gồm nhiều lệnh giúp kiểm tra gì?','What does a multi-command test verify?', [['Chuyển trạng thái','State transitions'],['Chỉ cú pháp include','Only include syntax']],0,'Lệnh sau phải quan sát đúng kết quả các lệnh trước.','Later commands must observe the state produced by earlier ones.');
 add('projects','project-delivery','Dự án: hoàn thiện và tự đánh giá','Project: validation and delivery','Đối chiếu đặc tả, độ phức tạp và các ca biên.','Review specification, complexity and boundary cases.',[
 ['Tiêu chí hoàn thành','Completion criteria','Một dự án hoàn tất khi biên dịch được, đáp ứng đặc tả và vượt các test đã thiết kế. Kiểm tra tên biến, hàm nhỏ, đầu vào lỗi và giới hạn tài nguyên. Ghi lại cách chạy để người khác tái hiện được kết quả.','A project is complete when it builds, meets its specification and passes designed tests. Review names, small functions, invalid input and resource limits. Record reproducible run instructions so another person can verify the same behavior.'],
 ['Đối chiếu hai cách','Compare two methods','Với miền nhỏ, dùng lời giải chậm nhưng rõ làm bộ đối chiếu cho lời giải nhanh. Ví dụ tổng 1..n bằng vòng lặp đối chiếu công thức n(n+1)/2. Chỉ thử trong miền không tràn số; test không chứng minh tính đúng cho mọi đầu vào.','On small inputs, use a simple slow implementation as an oracle for a faster one. Compare a loop summing 1..n against n(n+1)/2. Keep tests inside overflow-safe bounds; testing alone does not prove correctness on all inputs.']
 ],['iostream'],'    for(long long n=0;n<=100;++n) {\n        long long sum=0; for(long long i=1;i<=n;++i) sum+=i;\n        if(sum!=n*(n+1)/2) {std::cout<<"FAIL\\n"; return 1;}\n    }\n    std::cout<<"PASS 101\\n";','','PASS 101\n','Test đạt có chứng minh đúng với mọi đầu vào không?','Does passing tests prove correctness for every input?', [['Không','No'],['Có','Yes']],0,'Test xác nhận các ca đã chạy; lập luận và đặc tả vẫn cần thiết.','Tests confirm executed cases; reasoning and specification remain necessary.');
 // Named functions keep these introductory examples independent of lambda syntax.
 lessons.find(l=>l.id==='function-values').example.code='#include <iostream>\nlong long square(long long x) { return x*x; }\nint main() {\n    long long n; if (!(std::cin >> n) || n < -1000000000LL || n > 1000000000LL) return 0;\n    std::cout << square(n) << "\\n";\n}\n';
 lessons.find(l=>l.id==='references-tests').example.code='#include <iostream>\n#include <cassert>\nvoid swapValues(int& a, int& b) { int t=a; a=b; b=t; }\nint main() {\n    int a=2,b=7; swapValues(a,b); assert(a==7 && b==2);\n    std::cout << a << " " << b << "\\n";\n}\n';
 lessons.find(l=>l.id==='recursion').example.code='#include <iostream>\nlong long gcd(long long a,long long b) {\n    if(b==0) return a;\n    return gcd(b,a%b);\n}\nint main() {\n    long long a,b; if (!(std::cin>>a>>b) || a<0 || b<0) return 0;\n    std::cout << gcd(a,b) << "\\n";\n}\n';
 const practice=(chapterId,lesson,id,vi,en,sv,se,tests,solution,hv,he)=>exercises.push({chapterId,lesson,id,title:pair(vi,en),statement:pair(sv,se),tests,solution,hints:[pair(hv,he),pair('Đối chiếu các trường hợp biên và chỉ in đúng định dạng yêu cầu.','Check boundary cases and print only the required format.'),pair('Xem lời giải tham khảo, rồi tự viết lại và chạy toàn bộ test.','Study the reference, then rewrite it yourself and run every test.')]});
 exercises.forEach(e=>e.chapterId='start');
 practice('flow','loops','even-sum','A. Tổng số chẵn','A. Sum of even numbers','Đọc n, 0 ≤ n ≤ 1000000. In tổng các số chẵn trong [1,n].','Read n, 0 ≤ n ≤ 1000000. Print the sum of even integers in [1,n].',[['0\n','0\n'],['1\n','0\n'],['2\n','2\n'],['7\n','12\n'],['1000000\n','250000500000\n']],program(['iostream'],'    long long n; if(std::cin>>n) {long long k=n/2; std::cout<<k*(k+1)<<"\\n";}'),'Có floor(n/2) số chẵn; có thể cộng bằng vòng lặp.','There are floor(n/2) even integers; a loop can sum them.');
 practice('functions','recursion','gcd-practice','A. Ước chung lớn nhất','A. Greatest common divisor','Đọc a,b, 0 ≤ a,b ≤ 10^9. In gcd(a,b), quy ước gcd(0,0)=0.','Read a,b, 0 ≤ a,b ≤ 10^9. Print gcd(a,b), defining gcd(0,0)=0.',[['48 18\n','6\n'],['0 0\n','0\n'],['0 7\n','7\n'],['13 17\n','1\n'],['1000000000 1000000000\n','1000000000\n']],program(['iostream'],'    long long a,b; if(!(std::cin>>a>>b)) return 0;\n    while(b) {long long r=a%b; a=b; b=r;} std::cout<<a<<"\\n";'),'Áp dụng gcd(a,b)=gcd(b,a%b) tới khi b=0.','Apply gcd(a,b)=gcd(b,a%b) until b is zero.');
 practice('data','vectors','reverse-sequence','A. Đảo dãy','A. Reverse a sequence','Đọc n (0..100000), sau đó n số nguyên trong [-10^9,10^9]. In dãy đảo ngược, cách nhau một dấu cách, kết thúc bằng xuống dòng; dãy rỗng in dòng rỗng.','Read n (0..100000), then n integers in [-10^9,10^9]. Print them in reverse with single spaces and a final newline; an empty list produces an empty line.',[['0\n','\n'],['1\n-5\n','-5\n'],['4\n1 2 3 4\n','4 3 2 1\n'],['3\n2 2 2\n','2 2 2\n']],program(['iostream','vector'],'    int n; if(!(std::cin>>n)) return 0; std::vector<int>a(n); for(int&x:a)std::cin>>x;\n    for(int i=n-1;i>=0;--i) {if(i!=n-1)std::cout<<" ";std::cout<<a[i];} std::cout<<"\\n";'),'Duyệt từ n-1 về 0; chú ý dãy rỗng và dấu cách.','Traverse from n-1 to zero; handle empty input and spacing.');
 practice('memory','raii','owned-sum','A. Tổng vùng dữ liệu sở hữu','A. Sum owned data','Đọc n (0..100000), sau đó n số trong [-10^9,10^9]. Lưu bằng vector hoặc RAII, in tổng bằng long long; không dùng biến toàn cục hay cấp phát bị rò rỉ. Bộ chấm kiểm tra đầu ra; yêu cầu sở hữu cần tự rà code.','Read n (0..100000), then n numbers in [-10^9,10^9]. Store them using vector or RAII and print their long long sum. Avoid globals and leaks. Output tests do not verify the ownership style; review it separately.',[['0\n','0\n'],['1\n-9\n','-9\n'],['3\n1000000000 1000000000 1000000000\n','3000000000\n'],['4\n-2 2 -4 4\n','0\n']],program(['iostream','vector'],'    int n; if(!(std::cin>>n))return 0;std::vector<long long>a(n);long long sum=0;for(auto&x:a){std::cin>>x;sum+=x;}std::cout<<sum<<"\\n";'),'Vector tự giải phóng bộ nhớ khi rời phạm vi.','Vector releases its storage automatically on scope exit.');
 practice('objects','structs','best-student','A. Học viên điểm cao nhất','A. Highest-scoring student','Đọc n (1..1000), rồi n dòng tên ASCII không khoảng trắng (1..30 ký tự) và điểm (0..100). In tên và điểm cao nhất. Nếu hòa, chọn người xuất hiện trước.','Read n (1..1000), followed by n names (1..30 ASCII characters, no spaces) and scores (0..100). Print the highest-scoring name and score; on ties choose the earliest.',[['1\nAn 0\n','An 0\n'],['3\nAn 80\nBinh 95\nChi 90\n','Binh 95\n'],['2\nA 100\nB 100\n','A 100\n'],['2\nA 0\nB 1\n','B 1\n']],program(['iostream','string'],'    struct Student{std::string name;int score;};int n;if(!(std::cin>>n)||n<1)return 0;Student best;std::cin>>best.name>>best.score;for(int i=1;i<n;++i){Student s;std::cin>>s.name>>s.score;if(s.score>best.score)best=s;}std::cout<<best.name<<" "<<best.score<<"\\n";'),'Chỉ cập nhật khi điểm lớn hơn, không cập nhật khi bằng nhau.','Update only for a strictly greater score, preserving the earliest tie.');
 practice('stl','containers','distinct-count','A. Đếm giá trị phân biệt','A. Count distinct values','Đọc n (0..100000), sau đó n số nguyên trong [-10^9,10^9]. In số giá trị khác nhau.','Read n (0..100000), then n integers in [-10^9,10^9]. Print the number of distinct values.',[['0\n','0\n'],['1\n9\n','1\n'],['5\n1 2 1 -2 2\n','3\n'],['4\n7 7 7 7\n','1\n']],program(['iostream','set'],'    int n;if(!(std::cin>>n))return 0;std::set<int>s;for(int i=0,x;i<n;++i){std::cin>>x;s.insert(x);}std::cout<<s.size()<<"\\n";'),'Set chỉ giữ một bản của mỗi giá trị.','A set retains one copy of each distinct key.');
 practice('projects','project-statistics','statistics-project','A. Báo cáo thống kê','A. Statistics report','Đọc n (0..100000) và n số trong [-10^9,10^9]. Nếu n=0 in EMPTY. Ngược lại in nhỏ nhất, lớn nhất, tổng, cách nhau một dấu cách.','Read n (0..100000) and n numbers in [-10^9,10^9]. For n=0 print EMPTY; otherwise print minimum, maximum and sum separated by single spaces.',[['0\n','EMPTY\n'],['1\n-5\n','-5 -5 -5\n'],['4\n3 -2 8 1\n','-2 8 10\n'],['3\n1000000000 1000000000 1000000000\n','1000000000 1000000000 3000000000\n'],['3\n-2 0 2\n','-2 2 0\n']],lessons.find(l=>l.id==='project-statistics').example.code,'Xử lý dãy rỗng trước min/max và dùng tổng long long.','Handle empty input before min/max and accumulate in long long.');
 practice('flow','conditions','sign','B. Phân loại số','B. Classify a number','Đọc số nguyên x trong [-10^9,10^9]. In NEGATIVE nếu âm, ZERO nếu bằng 0, POSITIVE nếu dương.','Read integer x in [-10^9,10^9]. Print NEGATIVE for a negative value, ZERO for zero, or POSITIVE for a positive value.',[['-1000000000\n','NEGATIVE\n'],['0\n','ZERO\n'],['1000000000\n','POSITIVE\n']],lessons.find(l=>l.id==='conditions').example.code,'Chia thành ba nhánh loại trừ nhau.','Use three mutually exclusive branches.');
 practice('flow','nested-loops','triangle','C. Tam giác sao','C. Star triangle','Đọc n (0..20). In n dòng, dòng i (từ 1) có đúng i dấu *; n=0 không in gì.','Read n (0..20). Print n lines, with exactly i stars on line i (one-based); n=0 produces no output.',[['0\n',''],['1\n','*\n'],['4\n','*\n**\n***\n****\n']],lessons.find(l=>l.id==='nested-loops').example.code,'Vòng ngoài đếm dòng, vòng trong đếm dấu sao.','The outer loop counts rows and the inner loop prints stars.');
 practice('functions','function-values','square','B. Bình phương','B. Square','Đọc số nguyên n trong [-10^9,10^9]. Viết hàm tính bình phương và in kết quả. Test kiểm tra đầu ra; tự rà việc tách hàm.','Read integer n in [-10^9,10^9]. Write a square function and print its result. Tests check output; review the function decomposition separately.',[['0\n','0\n'],['-12\n','144\n'],['1000000000\n','1000000000000000000\n']],lessons.find(l=>l.id==='function-values').example.code,'Tính bằng long long ngay từ phép nhân.','Perform the multiplication in long long.');
 practice('functions','references-tests','swap','C. Đổi chỗ bằng tham chiếu','C. Swap through references','Đọc a,b trong [-10^9,10^9]. Viết hàm đổi chỗ nhận hai tham chiếu, rồi in a b sau đổi. Test đầu ra không xác minh cách truyền tham số.','Read a,b in [-10^9,10^9]. Write a swap function taking two references, then print a b after swapping. Output tests do not verify parameter-passing style.',[['2 7\n','7 2\n'],['0 0\n','0 0\n'],['-4 9\n','9 -4\n']], '#include <iostream>\nvoid exchange(int& a,int& b){int t=a;a=b;b=t;}\nint main(){int a,b;if(std::cin>>a>>b){exchange(a,b);std::cout<<a<<" "<<b<<"\\n";}}\n','Cần biến tạm để không mất giá trị ban đầu.','Use a temporary to preserve the original value.');
 practice('data','strings','ascii-letters','B. Đếm chữ ASCII','B. Count ASCII letters','Đọc một dòng không quá 100000 byte, chỉ gồm ASCII. In số ký tự A..Z hoặc a..z. Dòng rỗng cho kết quả 0.','Read one line of at most 100000 ASCII bytes. Print the count of A..Z and a..z characters. An empty line gives zero.',[['\n','0\n'],['Hello C++ 17\n','6\n'],['123 !?\n','0\n'],['aZ\n','2\n']],lessons.find(l=>l.id==='strings').example.code,'Dùng getline để không mất phần sau khoảng trắng.','Use getline to retain the text after spaces.');
 practice('data','prefix-sums','range-sum','C. Tổng đoạn','C. Range sum','Đọc n,q (0..100000), n số trong [-10^9,10^9], rồi q cặp l,r với 0 ≤ l ≤ r ≤ n. Với mỗi cặp, in tổng a[l..r), đánh số từ 0.','Read n,q (0..100000), n values in [-10^9,10^9], then q pairs l,r with 0 ≤ l ≤ r ≤ n. For each pair print the sum of zero-based a[l..r).', [['0 1\n0 0\n','0\n'],['4 3\n2 4 -1 5\n1 4\n0 4\n2 2\n','8\n10\n0\n'],['1 1\n-7\n0 1\n','-7\n']],program(['iostream','vector'],'    int n,q;if(!(std::cin>>n>>q))return 0;std::vector<long long>p(n+1);for(int i=0;i<n;++i){long long x;std::cin>>x;p[i+1]=p[i]+x;}while(q--){int l,r;std::cin>>l>>r;std::cout<<p[r]-p[l]<<"\\n";}'),'Xây p kích thước n+1 và trừ hai tổng tiền tố.','Build n+1 prefix entries and subtract two prefix sums.');
 practice('memory','pointers','pointer-update','B. Cập nhật qua địa chỉ','B. Update through an address','Đọc x,y trong [-10^9,10^9]. Dùng con trỏ tới x để gán y vào x, sau đó in x. Bộ test chỉ xác nhận giá trị, không xác nhận kỹ thuật con trỏ.','Read x,y in [-10^9,10^9]. Use a pointer to x to assign y to x, then print x. Tests verify the result, not the pointer technique.',[['1 7\n','7\n'],['0 -5\n','-5\n'],['9 9\n','9\n']],program(['iostream'],'    int x,y;if(!(std::cin>>x>>y))return 0;int* p=&x;*p=y;std::cout<<x<<"\\n";'),'Lấy địa chỉ x bằng &x rồi gán qua *p.','Take &x and assign through *p.');
 practice('memory','memory-safety','checked-access','C. Truy cập có kiểm tra','C. Checked access','Đọc n (0..100000), n số nguyên trong [-10^9,10^9], rồi chỉ số k (-1..100000). In a[k] nếu 0 ≤ k < n, ngược lại in OUT_OF_RANGE.','Read n (0..100000), n integers in [-10^9,10^9], then k (-1..100000). Print a[k] if 0 ≤ k < n, otherwise OUT_OF_RANGE.',[['0\n0\n','OUT_OF_RANGE\n'],['2\n4 8\n1\n','8\n'],['2\n4 8\n2\n','OUT_OF_RANGE\n'],['1\n9\n-1\n','OUT_OF_RANGE\n']],program(['iostream','vector'],'    int n;if(!(std::cin>>n))return 0;std::vector<int>a(n);for(int&x:a)std::cin>>x;int k;std::cin>>k;if(k<0||k>=n)std::cout<<"OUT_OF_RANGE\\n";else std::cout<<a[k]<<"\\n";'),'Kiểm tra cả cận dưới và cận trên trước khi đọc.','Check both bounds before accessing the element.');
 practice('objects','classes','account','B. Tài khoản đóng gói','B. Encapsulated account','Đọc số dư b và số tiền rút w, 0 ≤ b,w ≤ 10^9. Nếu w ≤ b, in số dư còn lại; nếu không in REJECTED. Dùng class để giữ số dư private; tự rà yêu cầu thiết kế này.','Read balance b and withdrawal w, 0 ≤ b,w ≤ 10^9. Print the remaining balance if w ≤ b, otherwise REJECTED. Keep balance private in a class; review this design requirement separately.',[['10 3\n','7\n'],['0 0\n','0\n'],['2 3\n','REJECTED\n'],['10 10\n','0\n']], '#include <iostream>\nclass Account{long long balance;public:explicit Account(long long b):balance(b){}bool withdraw(long long w){if(w>balance)return false;balance-=w;return true;}long long get()const{return balance;}};\nint main(){long long b,w;if(!(std::cin>>b>>w))return 0;Account a(b);if(a.withdraw(w))std::cout<<a.get()<<"\\n";else std::cout<<"REJECTED\\n";}\n','Kiểm tra trước khi đổi trạng thái; từ chối không được trừ tiền.','Validate before mutation; a rejected withdrawal must not change state.');
 practice('objects','polymorphism','shape-area','C. Diện tích qua giao diện','C. Area through an interface','Đọc S s hoặc R w h. Các kích thước nguyên trong [1,10^9]. In diện tích hình vuông S hoặc chữ nhật R. Dùng giao diện virtual; tự rà đa hình vì test chỉ kiểm tra đầu ra.','Read S s or R w h, with integer dimensions in [1,10^9]. Print square or rectangle area. Use a virtual interface; review polymorphism separately because tests only check output.',[['S 4\n','16\n'],['R 3 7\n','21\n'],['S 1\n','1\n'],['R 1000000000 1000000000\n','1000000000000000000\n']], '#include <iostream>\n#include <memory>\nstruct Shape{virtual long long area()const=0;virtual ~Shape()=default;};\nstruct Rectangle:Shape{long long w,h;Rectangle(long long a,long long b):w(a),h(b){}long long area()const override{return w*h;}};\nint main(){char kind;long long a,b;if(!(std::cin>>kind>>a))return 0;b=a;if(kind==\'R\'&&!(std::cin>>b))return 0;std::unique_ptr<Shape>s=std::make_unique<Rectangle>(a,b);std::cout<<s->area()<<"\\n";}\n','Một hình vuông có thể biểu diễn bằng hai cạnh bằng nhau.','A square can be represented by two equal dimensions.');
 practice('stl','sort-search','lower-position','B. Vị trí chèn','B. Insertion position','Đọc n (0..100000), n số và x trong [-10^9,10^9]. Sắp dãy tăng, in chỉ số từ 0 của phần tử đầu tiên ≥ x; nếu không có in n.','Read n (0..100000), n values and x in [-10^9,10^9]. Sort ascending and print the zero-based index of the first element ≥ x, or n if none exists.',[['0\n5\n','0\n'],['4\n7 2 4 2\n4\n','2\n'],['3\n1 1 1\n2\n','3\n'],['2\n3 5\n1\n','0\n']],program(['iostream','vector','algorithm'],'    int n;if(!(std::cin>>n))return 0;std::vector<int>a(n);for(int&v:a)std::cin>>v;int x;std::cin>>x;std::sort(a.begin(),a.end());std::cout<<(std::lower_bound(a.begin(),a.end(),x)-a.begin())<<"\\n";'),'Sắp xếp trước khi dùng lower_bound.','Sort the range before applying lower_bound.');
 practice('stl','dp-graphs','stairs','C. Đếm cách leo bậc','C. Count stair climbs','Đọc n (0..90). Mỗi bước leo 1 hoặc 2 bậc. In số cách lên đúng n bậc; n=0 có một cách rỗng. Thứ tự các bước khác nhau được tính riêng.','Read n (0..90). Each move climbs one or two stairs. Print the number of ways to reach exactly n; n=0 has one empty way. Different move orders count separately.',[['0\n','1\n'],['1\n','1\n'],['2\n','2\n'],['5\n','8\n'],['90\n','4660046610375530309\n']],lessons.find(l=>l.id==='dp-graphs').example.code,'Bước cuối dài 1 hoặc 2 nên cộng hai trạng thái trước.','The final move has length one or two, so add the preceding two states.');
 practice('projects','project-commands','commands','B. Bộ xử lý lệnh','B. Command processor','Đọc tối đa 1000 lệnh ADD x, GET, END, mỗi lệnh một dòng; |x| ≤ 10^6. Tổng ban đầu 0. ADD cộng x; GET in tổng; END dừng. Lệnh khác in ERROR và bỏ cả dòng. Đầu vào luôn đúng định dạng với lệnh hợp lệ.','Read at most 1000 commands ADD x, GET, END, one per line; |x| ≤ 10^6. Start at zero. ADD changes the total, GET prints it, END stops. Unknown commands print ERROR and discard the line. Valid commands always have valid arguments.',[['END\n',''],['GET\nEND\n','0\n'],['ADD 7\nADD -2\nGET\nEND\n','5\n'],['BAD 123\nGET\nEND\n','ERROR\n0\n']],lessons.find(l=>l.id==='project-commands').example.code,'Đừng để tham số của lệnh lạ trở thành lệnh tiếp theo.','Discard the rest of an unknown-command line.');
 practice('projects','project-delivery','sum-formula','C. Đối chiếu công thức','C. Validate a formula','Đọc n (0..10^9). In tổng 1+2+...+n bằng công thức O(1). Kiểm tra cách tính với vòng lặp trên n nhỏ trước khi nộp.','Read n (0..10^9). Print 1+2+...+n with an O(1) formula. Validate it against a loop on small n before submitting.',[['0\n','0\n'],['1\n','1\n'],['5\n','15\n'],['1000000000\n','500000000500000000\n']],program(['iostream'],'    long long n;if(std::cin>>n)std::cout<<n*(n+1)/2<<"\\n";'),'Nhân bằng long long trước khi chia cho 2.','Multiply using long long before dividing by two.');
 return{chapters,lessons,exercises};
})();
